-- Each reference must read the same produced rows; compare identities, not random snapshots.
drop database if exists cte_evaluation_identity;
create database cte_evaluation_identity;
use cte_evaluation_identity;
create table t(k int);
insert into t values(1),(2),(2),(null);
with r as(select rand() x) select count(*) from r a join r b on a.x=b.x;
with r as(select k,uuid() x from t) select count(*) from r a join r b on a.k<=>b.k and a.x=b.x;
with r as(select 1 k,rand() x union all select 2,rand()) select count(*) from r a join r b on a.k=b.k and a.x=b.x;
with recursive r(n,x) as(select 1,uuid() union all select n+1,x from r where n<5 limit 2 offset 1) select count(*) from r a join r b on a.n=b.n and a.x=b.x;
with r as(select uuid() x),s as(select x from r) select count(*) from s a join s b on a.x=b.x join r c on a.x=c.x;
with recursive base as(select uuid() x),r(n,x) as(select 1,x from base union all select n+1,base.x from r join base on r.x=base.x where n<3) select count(*) from r;
with recursive b as(select rand() x),r(n) as(select 1 union all select r.n+1 from r,b where r.n<3 and b.x>=0) select count(*),sum(n) from r;
select count(*) from (select k,(with recursive r(n) as(select (select t.k) union all select n+1 from r where n<3) select (select min(n) from r)+(select max(n) from r)) v from t) q where (k is null and v is null) or (k=1 and v=4) or (k=2 and v=5);
select count(*) from (select k,(with recursive r(n,s) as(select (select t.k),cast('a' as char(8)) union all select n+1,concat(s,'') from r where n<3) select (select min(n) from r)+(select max(n) from r)) v from t) q where (k is null and v is null) or (k=1 and v=4) or (k=2 and v=5);
select count(*) from (select k,(with r as(select result k from generate_series(1,3)g) select (select min(k) from r where k>=t.k)+(select max(k) from r)) v from t) q where (k is null and v is null) or (k=1 and v=4) or (k=2 and v=5);
with r as(select datediff('2026-01-03','2026-01-01')x) select count(*) from(select k,(select max(x) from r group by t.k)v from t)q where v=2;
with r as(select convert(extractvalue('<a>ok</a>','/a') using utf8mb4)x) select count(*) from(select k,(select max(x) from r group by t.k)v from t)q where v='ok';
create table dst(x varchar(100));
insert into dst with r(x) as(select uuid() union all select extractvalue('<a/>','[')) select x from r limit 1;
select count(*) from dst where length(x)=36;
insert into dst with r as(select uuid()x) select a.x from r a join r b on a.x=b.x;
select count(*) from dst where length(x)=36;
create table ctas_dst as with r(x) as(select uuid() union all select extractvalue('<a/>','[')) select x from r limit 1;
select count(*) from ctas_dst where length(x)=36;
drop database cte_evaluation_identity;
